 static int server_del(struct qrtr_node *node, unsigned int port, bool bcast)
 {
 	struct qrtr_lookup *lookup;
 	struct qrtr_server *srv;
 	struct list_head *li;

 	srv = xa_load(&node->servers, port);
 	if (!srv)
 		return -ENOENT;

 	xa_erase(&node->servers, port);

 	/* Broadcast the removal of local servers */
 	if (srv->node == qrtr_ns.local_node && bcast)
 		service_announce_del(&qrtr_ns.bcast_sq, srv);

 	/* Announce the service's disappearance to observers */
 	list_for_each(li, &qrtr_ns.lookups) {
 		lookup = container_of(li, struct qrtr_lookup, li);
 		if (lookup->service && lookup->service != srv->service)
 			continue;
 		if (lookup->instance && lookup->instance != srv->instance)
 			continue;

 		lookup_notify(&lookup->sq, srv, false);
 	}

 	kfree(srv);
+	node->server_count--;

 	return 0;
 }


 static void qrtr_ns_worker(struct work_struct *work)
 {
 	const struct qrtr_ctrl_pkt *pkt;
 	size_t recv_buf_size = 4096;
 	struct sockaddr_qrtr sq;
 	struct msghdr msg = { };
 	unsigned int cmd;
 	ssize_t msglen;
 	void *recv_buf;
 	struct kvec iv;
 	int ret;

 	msg.msg_name = (struct sockaddr *)&sq;
 	msg.msg_namelen = sizeof(sq);

 	recv_buf = kzalloc(recv_buf_size, GFP_KERNEL);
 	if (!recv_buf)
 		return;

 	for (;;) {
 		iv.iov_base = recv_buf;
 		iv.iov_len = recv_buf_size;

 		msglen = kernel_recvmsg(qrtr_ns.sock, &msg, &iv, 1,
 					iv.iov_len, MSG_DONTWAIT);

 		if (msglen == -EAGAIN)
 			break;

 		if (msglen < 0) {
 			pr_err("error receiving packet: %zd\n", msglen);
 			break;
 		}

 		pkt = recv_buf;
 		cmd = le32_to_cpu(pkt->cmd);
 		if (cmd < ARRAY_SIZE(qrtr_ctrl_pkt_strings) &&
 		    qrtr_ctrl_pkt_strings[cmd])
 			trace_qrtr_ns_message(qrtr_ctrl_pkt_strings[cmd],
 					      sq.sq_node, sq.sq_port);

 		ret = 0;
 		switch (cmd) {
 		case QRTR_TYPE_HELLO:
 			ret = ctrl_cmd_hello(&sq);
 			break;
 		case QRTR_TYPE_BYE:
 			ret = ctrl_cmd_bye(&sq);
 			break;
 		case QRTR_TYPE_DEL_CLIENT:
 			ret = ctrl_cmd_del_client(&sq,
 					le32_to_cpu(pkt->client.node),
 					le32_to_cpu(pkt->client.port));
 			break;
 		case QRTR_TYPE_NEW_SERVER:
 			ret = ctrl_cmd_new_server(&sq,
 					le32_to_cpu(pkt->server.service),
 					le32_to_cpu(pkt->server.instance),
 					le32_to_cpu(pkt->server.node),
 					le32_to_cpu(pkt->server.port));
 			break;
 		case QRTR_TYPE_DEL_SERVER:
 			ret = ctrl_cmd_del_server(&sq,
 					 le32_to_cpu(pkt->server.service),
 					 le32_to_cpu(pkt->server.instance),
 					 le32_to_cpu(pkt->server.node),
 					 le32_to_cpu(pkt->server.port));
 			break;
 		case QRTR_TYPE_EXIT:
 		case QRTR_TYPE_PING:
 		case QRTR_TYPE_RESUME_TX:
 			break;
 		case QRTR_TYPE_NEW_LOOKUP:
 			ret = ctrl_cmd_new_lookup(&sq,
 					 le32_to_cpu(pkt->server.service),
 					 le32_to_cpu(pkt->server.instance));
 			break;
 		case QRTR_TYPE_DEL_LOOKUP:
 			ctrl_cmd_del_lookup(&sq,
 				    le32_to_cpu(pkt->server.service),
 				    le32_to_cpu(pkt->server.instance));
 			break;
 		}

 		if (ret < 0)
-			pr_err("failed while handling packet from %d:%d",
+			pr_err_ratelimited("failed while handling packet from %d:%d",
 			       sq.sq_node, sq.sq_port);
 	}

 	kfree(recv_buf);
 }



